          "furniture": false
        },
        {
          "change": "same",
          "text": "SEC. 901. COMMISSION ORGANIZATION.",
          "furniture": false
        },
        {
          "change": "same",
          "text": "",
          "furniture": false
        },
        {
          "change": "same",
          "text": "    (a) Review of the Organization of the Commission.--",
          "furniture": false
        },
        {
          "change": "same",
          "text": "            (1) Review required.--Not later than 180 days after the",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        date of enactment of this Act, the Chairman of the Securities",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        and Exchange Commission shall conduct a review of the",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        organizational structure of the Commission, including the",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        offices and officials that report directly to the Chairman.",
          "furniture": false
        },
        {
          "change": "same",
          "text": "            (2) Reorganization.--Not later than 90 days after",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        completing the review required under paragraph (1), the",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        Chairman shall, to the extent practicable and consistent with",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        applicable law, reduce the number of offices and officials",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        reporting directly to the Chairman by reassigning such offices",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        and officials within the organizational structure of the",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        Commission.",
          "furniture": false
        },
        {
          "change": "same",
          "text": "            (3) Report.--Not later than 30 days after completing the",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        reorganization required under paragraph (2), the Chairman shall",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        submit to the Committee on Financial Services of the House of",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        Representatives and the Committee on Banking, Housing, and",
          "furniture": false
        },
        {
          "change": "same",
          "text": "        Urban Affairs of the Senate a report containing--",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                    (A) a description of the offices and officials that",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                reported directly to the Chairman on the date of",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                enactment of this Act;",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                    (B) an identification of the offices and officials",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                whose reporting relationships are required by statute;",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                    (C) a description of the changes made pursuant to",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                paragraph (2);",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                    (D) an identification of any offices or officials",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                that continue to report directly to the Chairman and",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                the reasons such reporting relationships were retained;",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                and",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                    (E) any legislative recommendations for further",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                reducing the number of offices and officials reporting",
          "furniture": false
        },
        {
          "change": "same",
          "text": "                directly to the Chairman.",
          "furniture": false
        },
        {
          "change": "same",
          "text": "            (4) Preservation of commission authority.--This subsection",
          "furniture": false
        },
